use super::*;
use super::super::KmoRowInfoData::KmoRowInfoData;
use serde_json::{Value,json};use std::panic::{catch_unwind,AssertUnwindSafe};
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");json!({"result":s.split(':').next().unwrap()})}}}
fn state(r:&KmoRowRange,qs:&Value)->Value{let mut i=r.iterator();let mut pairs=vec![];while i.hasNext(){let p=i.next();pairs.push(json!([p.first,p.second]));}json!({"text":r.toString(),"hash":r.hashCode(),"empty":r.isEmpty(),"size":r.getRangeSize(),"pairs":pairs,"queries":qs.as_array().unwrap().iter().map(|v|{let n=v.as_i64().unwrap()as i32;json!([r.containsRow(n),r.getRowCount(n)])}).collect::<Vec<_>>()})}
fn history(p:&Value)->Value{let r=KmoRowRange::new();let mut copy=None;let mut held=None;let mut rows=vec![];for op in p["ops"].as_array().unwrap(){let c=call(||match op[0].as_str().unwrap(){"add"=>{r.addRow(op[1].as_i64().unwrap()as i32);Value::Null},"remove"=>{r.removeRow(op[1].as_i64().unwrap()as i32);Value::Null},"copy"=>{copy=Some(r.clone());Value::Null},"copyAdd"=>{copy.as_ref().unwrap().addRow(op[1].as_i64().unwrap()as i32);Value::Null},"hold"=>{held=Some(r.iterator());Value::Null},"hasNext"=>json!(held.as_ref().unwrap().hasNext()),"next"=>{let p=held.as_mut().unwrap().next();json!([p.first,p.second])},_=>unreachable!()});let mut row=json!({"call":c,"state":state(&r,&p["queries"]),"equalsSelf":r.equals(Some(&r)),"equalsNull":r.equals(None),"equalsOther":r.equals(Some(&"other"))});if let Some(c)=&copy{row["copy"]=state(c,&p["queries"]);row["equalCopy"]=json!(r.equals(Some(c)));}rows.push(row);}json!({"rows":rows})}
fn data_state(d:&KmoRowInfoData)->Value{json!({"rowIndex":d.rowIndex,"raw_xfIndex":d.raw_xfIndex,"height":d.height,"option_flag":d.option_flag,"maxHeightCell":d.maxHeightCell,"minHeightCell":d.minHeightCell})}
fn datum(p:&Value)->Value{let a=p["args"].as_array().unwrap();let i=|n:usize|a[n].as_i64().unwrap()as i32;let mut d=match a.len(){1=>KmoRowInfoData::new(i(0)),4=>KmoRowInfoData::new__raw(i(0),i(1)as i16,i(2)as i16,i(3)as i16),_=>KmoRowInfoData::new__attrs(i(0),i(1)as i16,i(2)as i16,i(3)as i16,a[4].as_bool().unwrap(),a[5].as_bool().unwrap(),a[6].as_bool().unwrap(),a[7].as_bool().unwrap(),a[8].as_bool().unwrap(),a[9].as_bool().unwrap())};d.maxHeightCell=p["maxHeightCell"].as_i64().unwrap_or(-1)as i32;d.minHeightCell=p["minHeightCell"].as_i64().unwrap_or(-1)as i32;let mut c=d.copy();let mut o=json!({"state":data_state(&d),"copy":data_state(&c),"self":d.equals(Some(&d)),"null":d.equals(None),"equalCopy":d.equals(Some(&c)),"other":call(||d.equals(Some(&"other")))});c.rowIndex=p["otherRow"].as_i64().unwrap_or(i32::MIN as i64)as i32;o["differentRowEqual"]=json!(d.equals(Some(&c)));c.height=c.height.wrapping_add(1);o["differentHeightEqual"]=json!(d.equals(Some(&c)));o}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
#[test]fn original_android_row_ranges_and_row_data(){let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/row-range-r0b68");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let actual=json!({"histories":input["histories"].as_array().unwrap().iter().map(history).collect::<Vec<_>>(),"data":input["data"].as_array().unwrap().iter().map(datum).collect::<Vec<_>>()});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();compare(&actual,&java,"root");}
